#import <Foundation/Foundation.h>
#import <AppKit/AppKit.h>

// Function to find accessibility element
static AXUIElementRef FindElementByRole(AXUIElementRef parent, CFStringRef role) {
    CFArrayRef children = NULL;
    AXUIElementCopyAttributeValue(parent, kAXChildrenAttribute, (CFTypeRef *)&children);

    if (!children) return NULL;

    for (int i = 0; i < CFArrayGetCount(children); i++) {
        AXUIElementRef child = (AXUIElementRef)CFArrayGetValueAtIndex(children, i);

        CFStringRef childRole = NULL;
        AXUIElementCopyAttributeValue(child, kAXRoleAttribute, (CFTypeRef *)&childRole);

        if (childRole && CFStringCompare(childRole, role, 0) == kCFCompareEqualTo) {
            CFRelease(children);
            return child;
        }

        AXUIElementRef found = FindElementByRole(child, role);
        if (found) {
            CFRelease(children);
            return found;
        }

        if (childRole) CFRelease(childRole);
    }

    CFRelease(children);
    return NULL;
}

int main() {
    // Get the accessibility element for the active application
    pid_t simPid = 0;

    for (NSRunningApplication *app in [[NSWorkspace sharedWorkspace] runningApplications]) {
        if ([app.bundleIdentifier isEqualToString:@"com.apple.iphonesimulator"]) {
            simPid = app.processIdentifier;
            NSLog(@"Found iOS Simulator with PID: %d", simPid);
            break;
        }
    }

    if (simPid == 0) {
        NSLog(@"iOS Simulator not found");
        return 1;
    }

    // Create AXUIElement for the Simulator process
    AXUIElementRef appRef = AXUIElementCreateApplication(simPid);

    if (!appRef) {
        NSLog(@"Failed to create AXUIElement for Simulator");
        return 1;
    }

    // Try to find search field
    AXUIElementRef searchField = FindElementByRole(appRef, CFSTR("AXSearchField"));

    if (!searchField) {
        NSLog(@"Search field not found");
        CFRelease(appRef);
        return 1;
    }

    NSLog(@"Found search field!");

    // Try to focus the search field and type
    // Note: This will still use keyboard events, which may be restricted

    // Alternative: Try to set the value directly
    CFStringRef searchText = CFSTR("Book");
    AXError error = AXUIElementSetAttributeValue(searchField, kAXValueAttribute, searchText);

    if (error == kAXErrorSuccess) {
        NSLog(@"Successfully set search field value to 'Book'");
    } else {
        NSLog(@"Failed to set search field value: %d", error);
    }

    CFRelease(appRef);

    return 0;
}
