import AppKit
import CoreGraphics

// Try to send keyboard input to the iOS Simulator
// by directly using CoreGraphics keyboard events

func sendKeyboardText(_ text: String) {
    let eventSource = CGEventSource(stateID: .hidd)

    for char in text {
        // Convert character to key code
        let keyCode: CGKeyCode

        switch char.lowercased() {
        case "b": keyCode = 11
        case "o": keyCode = 31
        case "k": keyCode = 40
        default: continue
        }

        // Send key down event
        if let keyDown = CGEvent(keyboardEventSource: eventSource, virtualKey: keyCode, keyDown: true) {
            keyDown.post(tap: .cghidEventTap)
        }

        // Send key up event
        if let keyUp = CGEvent(keyboardEventSource: eventSource, virtualKey: keyCode, keyDown: false) {
            keyUp.post(tap: .cghidEventTap)
        }

        usleep(100000) // 100ms delay between keystrokes
    }
}

